const PI={obj:['Vật kính (thấu kính)','Thấu kính phía trước thu ánh sáng và hội tụ về tiêu điểm. Khẩu độ càng lớn, ảnh càng sáng và nhiều chi tiết.','Ở miệng ống, nơi ánh sáng đi vào; achromat dùng 2 thấu kính ghép để giảm viền màu.'],pri:['Gương chính','Gương lõm thu sáng và phản xạ ngược lên. Là bộ phận đắt và quan trọng nhất.',{new:'Ở đáy ống, trong cell có 3 vít chỉnh quang.',sct:'Ở cuối ống; dịch chuyển để lấy nét.'}],sec:['Gương phụ','Gương nhỏ đưa chùm sáng ra thị kính. Trong Newton nó nghiêng 45° và đưa ánh sáng ra bên hông; trong SCT nó phản xạ ngược qua lỗ gương chính.',{new:'Gần miệng ống, giữ bằng chân nhện (spider).',sct:'Gắn ở tâm tấm hiệu chỉnh.'}],cor:['Tấm hiệu chỉnh','Kính phẳng sửa méo hình và đóng kín ống, chống bụi.','Ở miệng ống; gương phụ gắn ở tâm.'],tube:['Thân ống','Giữ các quang cụ thẳng hàng và chắn ánh sáng lạc. Sơn đen mờ bên trong.','Chiều dài gần bằng tiêu cự (Newton, khúc xạ); SCT chỉ khoảng 1/3.'],dew:['Chụp chống sương','Ống nối dài ngăn sương đọng lên quang cụ và giảm ánh sáng lạc. Đêm ẩm rất cần.','Gắn ở miệng ống.'],foc:['Bộ chỉnh nét','Cơ cấu răng đẩy thị kính tới lui để lấy nét; phải trơn, không rơ.',{ref:'Ở đuôi ống.',new:'Bên hông ống, gần miệng ống.'}],dia:['Gương/lăng kính 90°','Bẻ chùm sáng xuống để nhìn thoải mái. Ở SCT gồm cả cụm đuôi.','Cắm vào bộ chỉnh nét; thị kính cắm vào nó.'],bar:['Barlow ×2','Thấu kính nhân đôi phóng đại của mọi thị kính, không cần mua thêm thị kính.','Cắm giữa bộ chỉnh nét (hoặc gương 90°) và thị kính.'],eye:['Thị kính','Phóng to ảnh: phóng đại = tiêu cự kính ÷ tiêu cự thị kính. Thị kính 25 mm để tìm vật, 6–10 mm để ngắm chi tiết.','Cắm vào ống chuẩn 31,75 mm của bộ chỉnh nét.'],cam:['Adapter điện thoại / camera','Giữ điện thoại hoặc camera để chụp ảnh qua thị kính; in 3D được.','Gắn trên thị kính, giữ đúng tâm.'],fnd:['Ống ngắm (finder)','Kính nhỏ trường rộng để nhắm tới mục tiêu: chấm đỏ hoặc 9×50. Gần như bắt buộc vì ống chính chỉ thấy một vùng rất nhỏ.','Gắn trên thân ống, song song trục chính, gần thị kính.'],mnt:['Giá đỡ','Giữ kính vững và cho phép xoay. Rung lắc là lỗi gây khó chịu nhất khi quan sát ở phóng đại cao.','']};
