function evs(){const P=29.530588853,J=2451550.26,jd=Date.now()/864e5+2440587.5,n0=Math.floor((jd-J)/(P/4))+1;$('#ev').innerHTML='<b>Pha Mặt Trăng sắp tới</b> (xấp xỉ, lệch tối đa khoảng 14 giờ): '+[0,1,2,3].map(i=>{const n=n0+i;return['Trăng mới','Bán nguyệt đầu tháng','Trăng tròn','Bán nguyệt cuối tháng'][n%4]+' '+new Date((J+P*n/4-2440587.5)*864e5).toLocaleDateString('vi-VN')}).join(' · ')}
const LS=[
['Bầu trời và thiên cầu',1,'Hơn 2.000 năm trước, theo truyền thống ghi nhận, Hipparchus lập một bảng sao và chia độ sáng thành 6 bậc: sao sáng nhất là cấp 1, sao mờ nhất mắt thường thấy là cấp 6. Hệ thống ấy sống đến ngày nay; người ta chỉ chuẩn hóa để hai cấp chênh nhau 5 bậc là sáng gấp đúng 100 lần.',['Thiên cầu là quả cầu tưởng tượng bao quanh Trái Đất; sao dường như quay quanh cực thiên cầu vì Trái Đất tự quay.','Chòm sao chỉ là hình ghép trên bầu trời; các sao trong một chòm thường ở rất xa nhau.','Cấp sao càng nhỏ càng sáng; mắt thường ở nơi tối thấy tới khoảng cấp 6.','Mặt Trời mọc đằng Đông, lặn đằng Tây vì Trái Đất quay từ Tây sang Đông.'],[[['m1','Cấp sao thứ nhất',1],['m2','Cấp sao thứ hai',6]],v=>`Sao cấp ${v.m1} sáng gấp ${(10**(.4*(v.m2-v.m1))).toFixed(2)} lần sao cấp ${v.m2}.`],[['Sao cấp 1 so với sao cấp 6 thì:',['Sáng gấp 100 lần','Sáng gấp 5 lần','Mờ hơn 100 lần','Bằng nhau'],0,'Chênh 5 cấp tương đương 100 lần.'],['Vì sao sao dường như quay quanh một điểm trên trời?',['Trái Đất tự quay quanh trục','Sao quay quanh Trái Đất','Mặt Trời kéo chúng','Khí quyển cuốn chúng'],0,'Chuyển động hàng ngày là do Trái Đất tự quay.'],['Mắt thường ở nơi tối thấy sao tới cấp khoảng:',['2','6','12','20'],1,'Giới hạn kinh điển là cấp 6.']]],
['Khẩu độ và lịch sử kính thiên văn',1,'Năm 1608, thợ làm kính Hans Lippershey xin cấp bằng sáng chế một ống nhìn xa ở Hà Lan. Cuối năm 1609, Galileo tự chế kính phóng đại khoảng 20 lần; trong khoảng một năm sau đó ông thấy núi trên Mặt Trăng, bốn vệ tinh của Mộc tinh (tháng 1/1610) và pha của Kim tinh (cuối 1610), những bằng chứng ủng hộ mô hình Mặt Trời là trung tâm. Năm 1668, Newton dựng kính phản xạ để tránh viền màu của thấu kính.',['Kính khúc xạ dùng thấu kính; kính phản xạ dùng gương; kính hỗn hợp (SCT) dùng cả hai.','Khẩu độ quyết định lượng ánh sáng thu được và độ phân giải.','Thế kỷ 20: kính lớn trên núi cao; rồi kính không gian Hubble (1990) và James Webb (2021) thoát khỏi khí quyển.','Người yêu thiên văn nghiệp dư vẫn phát hiện sao chổi và sao siêu mới ngày nay.'],0,[['Tháng 1/1610, Galileo thấy gì qua kính tự chế?',['Bốn vệ tinh lớn của Mộc tinh','Sao Hải Vương','Vành đai Thiên Vương tinh','Hố đen'],0,'Ông thấy 4 vệ tinh quay quanh Mộc tinh.'],['Newton chế kính phản xạ chủ yếu để tránh:',['Viền màu (sắc sai) của thấu kính','Ánh sáng Mặt Trời','Sương mù','Tiếng ồn'],0,'Gương không gây sắc sai.'],['Yếu tố quan trọng nhất của kính là:',['Màu sơn','Độ phóng đại quảng cáo','Khẩu độ','Giá tiền'],2,'Khẩu độ quyết định độ sáng và độ phân giải.']]],
['Hệ Mặt Trời và định luật Kepler',2,'Tycho Brahe dành hơn 20 năm đo vị trí hành tinh bằng mắt thường với độ chính xác chưa từng có. Trợ lý của ông là Kepler dùng số liệu về Hỏa tinh, thử rất nhiều quỹ đạo và năm 1609 nhận ra quỹ đạo là elip chứ không phải đường tròn. Năm 1619 ông tìm ra định luật thứ ba.',['Định luật 1: quỹ đạo là elip, Mặt Trời ở một tiêu điểm.','Định luật 2: đường nối hành tinh với Mặt Trời quét diện tích bằng nhau trong thời gian bằng nhau, nên gần Mặt Trời thì chạy nhanh hơn.','Định luật 3: T² = a³ (T tính bằng năm, a bằng AU).','Hệ gồm 8 hành tinh: hành tinh đá ở trong, hành tinh khí và băng khổng lồ ở ngoài.'],[[['a','Nửa trục lớn a (AU)',4]],v=>`Chu kỳ T = ${(v.a**1.5).toFixed(2)} năm (${(v.a**1.5*365.25).toFixed(0)} ngày).`],[['Hành tinh có a = 4 AU có chu kỳ:',['4 năm','8 năm','16 năm','2 năm'],1,'T = 4^1,5 = 8 năm.'],['Hành tinh chạy nhanh nhất khi ở:',['Điểm cận nhật','Điểm viễn nhật','Luôn như nhau','Khi gặp Mặt Trăng'],0,'Gần Mặt Trời nhất thì nhanh nhất.'],['Quỹ đạo hành tinh có dạng:',['Hình tròn hoàn hảo','Elip','Parabol','Đường thẳng'],1,'Định luật 1 của Kepler.']]],
['Mặt Trăng, pha và nhật nguyệt thực',2,'Thế kỷ 5 trước Công nguyên, Anaxagoras giải thích Mặt Trăng chỉ phản chiếu ánh sáng Mặt Trời. Theo ghi chép, năm 1504 Columbus đã dùng một lần nguyệt thực được tính trước để thuyết phục người bản xứ ở Jamaica tiếp tục cung cấp lương thực cho thủy thủ của mình.',['Mặt Trăng luôn sáng một nửa; ta thấy pha đổi vì góc nhìn từ Trái Đất đổi.','Chu kỳ pha 29,53 ngày, dài hơn chu kỳ quay quanh Trái Đất 27,32 ngày.','Nhật thực: Trăng mới che Mặt Trời; nguyệt thực: Trăng tròn vào bóng Trái Đất.','Quỹ đạo nghiêng khoảng 5° nên không phải tháng nào cũng có thực.','Mặt Trăng luôn hướng một mặt về Trái Đất (khóa thủy triều).'],'moon',[['Nguyệt thực xảy ra vào:',['Trăng tròn','Trăng mới','Bán nguyệt','Bất kỳ lúc nào'],0,'Trái Đất nằm giữa Mặt Trời và Mặt Trăng.'],['Vì sao không có nhật thực mỗi tháng?',['Quỹ đạo Trăng nghiêng khoảng 5°','Mặt Trăng quá nhỏ','Trái Đất che','Mặt Trời tắt'],0,'Chỉ khi Trăng mới ở gần giao điểm quỹ đạo mới có nhật thực.'],['Ta luôn thấy cùng một mặt Mặt Trăng vì:',['Tự quay bằng chu kỳ quỹ đạo (khóa thủy triều)','Mặt Trăng không quay','Mặt kia tối','Trái Đất đứng yên'],0,'Hai chu kỳ bằng nhau.']]],
['Quang học của kính',3,'Khoảng năm 1758, John Dollond chế thấu kính ghép hai loại thủy tinh để giảm viền màu, mở đường cho kính khúc xạ tốt. Còn gương parabol được thử bằng phương pháp dao Foucault từ năm 1858; ngày nay nhiều người vẫn tự mài gương theo cách đó.',['Phóng đại = tiêu cự kính ÷ tiêu cự thị kính.','Đồng tử ra = khẩu độ ÷ phóng đại; nên nằm trong khoảng 0,5–7 mm.','Độ phân giải Dawes ≈ 116″ ÷ khẩu độ (mm).','Phóng đại hữu ích tối đa ≈ 2 × khẩu độ (mm); seeing thường giới hạn trước.'],[[['D','Khẩu độ (mm)',150],['F','Tiêu cự kính (mm)',750],['fe','Tiêu cự thị kính (mm)',10]],v=>{const m=v.F/v.fe;return`Phóng đại ${m.toFixed(0)}×, đồng tử ra ${(v.D/m).toFixed(1)} mm, phân giải ${(116/v.D).toFixed(2)}″. ${m>2*v.D?'Vượt 2× khẩu độ, ảnh sẽ mờ.':'Nằm trong giới hạn hữu ích.'}`}],[['Kính F=1000 mm, thị kính 10 mm cho phóng đại:',['10×','100×','1000×','50×'],1,'1000 ÷ 10 = 100.'],['Kính khẩu độ 150 mm, tối đa hữu ích khoảng:',['150×','300×','75×','1500×'],1,'2 × 150 = 300.'],['Độ phân giải Dawes của kính 116 mm là:',['1″','2″','116″','0,1″'],0,'116 ÷ 116 = 1.']]],
['Sao, thiên hà và khoảng cách',3,'Năm 1912, Henrietta Leavitt phát hiện sao Cepheid càng sáng thì chu kỳ biến quang càng dài, tạo ra một “con độ” đo khoảng cách. Năm 1924, Edwin Hubble dùng nó để chứng minh Andromeda nằm ngoài Ngân Hà, và đến năm 1929 vũ trụ được nhận ra đang giãn nở.',['1 năm ánh sáng ≈ 9,46 nghìn tỉ km; 1 parsec ≈ 3,26 năm ánh sáng.','Độ sáng biểu kiến m phụ thuộc độ sáng thực M và khoảng cách: m − M = 5 log₁₀(d/10 pc).','Mặt Trời là một trong vài trăm tỉ sao của Ngân Hà; Andromeda cách khoảng 2,5 triệu năm ánh sáng.','Sao có vòng đời: tinh vân, dãy chính, khổng lồ đỏ, rồi sao lùn trắng, sao neutron hoặc hố đen.'],[[['m','Độ sáng biểu kiến m',5],['M','Độ sáng tuyệt đối M',0]],v=>{const d=10**((v.m-v.M+5)/5);return`Khoảng cách ≈ ${d.toFixed(1)} parsec ≈ ${(d*3.26156).toFixed(1)} năm ánh sáng.`}],[['Ánh sáng từ Mặt Trời tới Trái Đất mất khoảng:',['8 phút','8 giây','8 giờ','1 ngày'],0,'Khoảng 499 giây.'],['Sao Cepheid giúp ta:',['Đo khoảng cách thiên hà','Đo nhiệt độ Trái Đất','Dự báo thời tiết','Đếm hành tinh'],0,'Chu kỳ biến quang cho biết độ sáng thực.'],['Thiên hà Andromeda cách chúng ta khoảng:',['2,5 triệu năm ánh sáng','2,5 nghìn năm ánh sáng','25 năm ánh sáng','250 tỉ năm ánh sáng'],0,'Ngày nay ta thấy nó như 2,5 triệu năm trước.']]]];
LS[0][3].push('Tọa độ thiên cầu: xích kinh (RA) và xích vĩ (Dec) giống kinh độ và vĩ độ trên bầu trời; độ cao của cực Bắc thiên cầu bằng vĩ độ người quan sát (Hà Nội khoảng 21°).');LS[0][5].push(['Độ cao của sao Bắc Cực trên chân trời xấp xỉ bằng:',['Vĩ độ của người quan sát','Kinh độ của người quan sát','90°','0°'],0,'Độ cao cực thiên cầu bằng vĩ độ.'],['Xích kinh và xích vĩ tương ứng với:',['Kinh độ và vĩ độ trên bầu trời','Độ cao và phương vị','Cấp sao và màu sao','Khoảng cách và tuổi sao'],0,'Đây là hệ tọa độ xích đạo.']);
LS[1][3].push('Kính khúc xạ lớn nhất thế giới ở Đài Yerkes (1897) có khẩu độ khoảng 1 mét; thấu kính chỉ giữ được ở rìa nên lớn hơn nữa sẽ bị võng, vì vậy mọi kính cực lớn đều là kính phản xạ.');LS[1][5].push(['Vì sao các kính lớn nhất đều là kính phản xạ?',['Gương đỡ được từ phía sau nên làm được rất lớn','Thấu kính không hội tụ được ánh sáng','Gương luôn rẻ hơn mọi thứ','Thấu kính chỉ dùng ban ngày'],0,'Thấu kính quá lớn sẽ võng dưới sức nặng của chính nó.'],['Kính Hubble ở ngoài không gian giúp tránh được:',['Nhiễu loạn của khí quyển','Ánh sáng Mặt Trời','Trọng lực','Từ trường'],0,'Ngoài khí quyển không có seeing.']);
LS[2][3].push('1 AU ≈ 149,6 triệu km; ánh sáng đi từ Mặt Trời tới Trái Đất mất khoảng 8,3 phút.');LS[2][5].push(['1 AU xấp xỉ bằng:',['150 triệu km','150 nghìn km','1,5 tỉ km','15 triệu km'],0,'Khoảng cách trung bình Trái Đất đến Mặt Trời.'],['Kepler dùng số liệu của ai để tìm ra các định luật?',['Tycho Brahe','Galileo','Newton','Hubble'],0,'Số liệu quan sát Hỏa tinh của Tycho.']);
LS[3][3].push('Mặt Trăng xa dần Trái Đất khoảng 3,8 cm mỗi năm; thủy triều dâng hạ do lực hấp dẫn của Mặt Trăng và Mặt Trời, mạnh nhất (triều cường) khi Trăng mới và Trăng tròn.');LS[3][5].push(['Triều cường xảy ra khi:',['Trăng mới hoặc Trăng tròn','Trăng bán nguyệt','Chỉ khi có nhật thực','Không bao giờ'],0,'Lực hút của Mặt Trời và Mặt Trăng cộng lại.'],['Chu kỳ pha (29,53 ngày) dài hơn chu kỳ quay quanh Trái Đất (27,32 ngày) vì:',['Trái Đất cũng di chuyển quanh Mặt Trời','Mặt Trăng chậm lại','Trái Đất quay chậm','Sai số đo'],0,'Trăng phải đi thêm một đoạn để trở lại cùng pha.']);
LS[4][3].push('Quang sai thường gặp: sắc sai (kính khúc xạ), coma (Newton khẩu độ nhanh) và cầu sai (gương cầu); gương parabol loại bỏ cầu sai.');LS[4][5].push(['Gương parabol được dùng để:',['Loại bỏ cầu sai','Tăng viền màu','Giảm khẩu độ','Làm ảnh ngược'],0,'Gương cầu hội tụ không đều về một điểm.'],['Đồng tử ra của kính khẩu độ 200 mm ở 100× là:',['2 mm','20 mm','0,5 mm','200 mm'],0,'200 ÷ 100 = 2.']);
LS[5][3].push('Cấp sao tuyệt đối M là cấp sao nếu sao ở cách 10 parsec; Mặt Trời có M ≈ 4,83, còn cấp sao biểu kiến của nó là −26,7.');LS[5][5].push(['Mặt Trời có cấp sao tuyệt đối khoảng:',['4,8','−26,7','0','10'],0,'−26,7 là cấp sao biểu kiến.'],['Sao có m − M = 5 cách chúng ta:',['100 parsec','10 parsec','1 parsec','5 parsec'],0,'d = 10^((5+5)/5) = 100 pc.']);
LS.push(['Lịch sử khám phá các thiên thể',2,'Năm 1781, nhà thiên văn nghiệp dư William Herschel dùng kính tự chế quét bầu trời và thấy một “sao” có đĩa nhỏ; ông tưởng là sao chổi, nhưng đó là Thiên Vương tinh, hành tinh đầu tiên được phát hiện bằng kính. Sau đó người ta thấy quỹ đạo của nó bị lệch, và năm 1846 Le Verrier tính ra vị trí một hành tinh chưa ai thấy; ngay đêm đầu tiên tìm kiếm, Galle ở Berlin đã thấy Hải Vương tinh gần đúng chỗ đó.',['Thủy, Kim, Hỏa, Mộc, Thổ được biết từ thời cổ vì thấy được bằng mắt thường; chữ planet gốc Hy Lạp nghĩa là kẻ lang thang.','1610: Galileo thấy 4 vệ tinh của Mộc tinh. 1655: Huygens phát hiện Titan và giải thích vành đai Sao Thổ. 1675: Cassini tìm ra khe chia vành đai.','1801: Piazzi phát hiện Ceres, tiểu hành tinh đầu tiên. 1930: Tombaugh phát hiện Pluto; năm 2006 Liên đoàn Thiên văn Quốc tế xếp Pluto vào nhóm hành tinh lùn.','Kỷ nguyên tàu vũ trụ: Voyager 2 (phóng 1977) là tàu duy nhất bay qua Thiên Vương tinh (1986) và Hải Vương tinh (1989).','1995: Mayor và Queloz phát hiện ngoại hành tinh đầu tiên quanh một sao giống Mặt Trời (51 Pegasi b); nay đã biết hàng nghìn ngoại hành tinh.'],[[['a','Khoảng cách tàu vũ trụ (AU)',30.07]],v=>`Tín hiệu vô tuyến mất ${(v.a*8.317).toFixed(1)} phút (${(v.a*8.317/60).toFixed(1)} giờ) để đi một chiều.`],[['Ai phát hiện Thiên Vương tinh năm 1781?',['William Herschel','Galileo','Tombaugh','Le Verrier'],0,'Ban đầu ông nghĩ đó là sao chổi.'],['Hải Vương tinh được tìm ra bằng cách nào?',['Tính từ nhiễu loạn quỹ đạo Thiên Vương tinh rồi tìm đúng chỗ','Tình cờ khi chụp ảnh','Nhìn bằng mắt thường','Do tàu vũ trụ chụp'],0,'Le Verrier tính, Galle quan sát năm 1846.'],['Năm 2006 Pluto được xếp lại là:',['Hành tinh lùn','Vệ tinh','Sao chổi','Tiểu hành tinh'],0,'Sau khi có định nghĩa mới về hành tinh.'],['Vệ tinh nào do Huygens phát hiện năm 1655?',['Titan','Io','Europa','Triton'],0,'Titan là vệ tinh lớn nhất của Sao Thổ.'],['Tàu nào duy nhất đã bay qua cả Thiên Vương tinh và Hải Vương tinh?',['Voyager 2','Voyager 1','Cassini','Hubble'],0,'Voyager 2 vào các năm 1986 và 1989.']]],['Đặc điểm các hành tinh',2,'Năm 1877, Schiaparelli ghi lại các “canali” trên Hỏa tinh; Percival Lowell tin đó là kênh đào của người ngoài hành tinh. Năm 1965 tàu Mariner 4 bay qua và chụp được bề mặt đầy hố va chạm, chấm dứt giấc mơ về kênh đào.',['Bốn hành tinh đá (Thủy, Kim, Trái Đất, Hỏa) có bề mặt rắn; bốn hành tinh ngoài gồm hai khí khổng lồ (Mộc, Thổ) và hai băng khổng lồ (Thiên Vương, Hải Vương).','Kim tinh nóng nhất, khoảng 465°C vì khí quyển CO₂ dày; nó quay ngược chiều các hành tinh khác.','Hỏa tinh có núi lửa Olympus Mons cao khoảng 22 km, hai vệ tinh nhỏ Phobos và Deimos, và băng ở hai cực.','Mộc tinh lớn nhất, nặng gấp khoảng 2,5 lần mọi hành tinh khác cộng lại; Vết Đỏ là cơn bão tồn tại hàng trăm năm.','Thổ tinh có khối lượng riêng nhỏ hơn nước; vành đai gồm băng và đá, rất mỏng so với bề rộng.','Thiên Vương tinh có trục nghiêng khoảng 98° như đang lăn trên quỹ đạo; Hải Vương tinh có gió mạnh nhất, tới hơn 2.000 km/h.'],[[['kg','Khối lượng của bạn (kg)',50],['g','Gia tốc rơi tự do g (m/s²), ví dụ Hỏa tinh 3,71',3.71]],v=>`Trọng lượng ${(v.kg*v.g).toFixed(0)} N, tương đương ${(v.kg*v.g/9.81).toFixed(1)} kg trên Trái Đất.`],[['Hành tinh nóng nhất Hệ Mặt Trời là:',['Kim tinh','Thủy tinh','Hỏa tinh','Mộc tinh'],0,'Hiệu ứng nhà kính CO₂, khoảng 465°C.'],['Hành tinh có trục quay nghiêng khoảng 98° là:',['Thiên Vương tinh','Hải Vương tinh','Thổ tinh','Hỏa tinh'],0,'Trục gần như nằm ngang.'],['Núi lửa Olympus Mons cao khoảng 22 km nằm trên:',['Hỏa tinh','Kim tinh','Mặt Trăng','Thủy tinh'],0,'Là núi lớn nhất đã biết trong Hệ Mặt Trời.'],['Hành tinh có khối lượng riêng nhỏ hơn nước là:',['Thổ tinh','Thủy tinh','Trái Đất','Hỏa tinh'],0,'Khoảng 0,69 g/cm³.'],['Hai hành tinh khí khổng lồ là:',['Mộc tinh và Thổ tinh','Thủy tinh và Kim tinh','Trái Đất và Hỏa tinh','Thiên Vương tinh và Hải Vương tinh'],0,'Hai hành tinh ngoài cùng là băng khổng lồ.']]],['Hấp dẫn của Newton',3,'Năm 1687, trong cuốn Principia, Newton chỉ ra rằng cùng một lực hấp dẫn làm quả táo rơi và giữ Mặt Trăng trên quỹ đạo. Edmond Halley dùng lý thuyết đó để chứng minh các sao chổi năm 1531, 1607 và 1682 là một, và dự đoán nó trở lại năm 1758; ông mất 16 năm trước đó, nhưng sao chổi đã quay lại đúng hẹn.',['Lực hấp dẫn F = G·M·m / r²: tỉ lệ thuận với tích khối lượng, tỉ lệ nghịch với bình phương khoảng cách.','Quỹ đạo là sự rơi liên tục: vật chuyển động ngang đủ nhanh nên mãi rơi mà không chạm đất.','Vận tốc thoát v = √(2GM/r): khoảng 11,2 km/s với Trái Đất, 2,4 km/s với Mặt Trăng.','Định luật Kepler thứ ba suy ra từ hấp dẫn của Newton, và cho phép cân khối lượng hành tinh bằng chu kỳ vệ tinh của nó.'],[[['M','Khối lượng (lần Trái Đất)',1],['r','Bán kính (lần Trái Đất)',1]],v=>`Vận tốc thoát ≈ ${(11.186*Math.sqrt(v.M/v.r)).toFixed(1)} km/s.`],[['Lực hấp dẫn giữa hai vật tỉ lệ nghịch với:',['Bình phương khoảng cách','Khoảng cách','Khối lượng','Thời gian'],0,'F = GMm/r².'],['Nếu khoảng cách tăng gấp đôi, lực hấp dẫn:',['Giảm còn 1/4','Giảm còn 1/2','Tăng gấp đôi','Không đổi'],0,'Tỉ lệ nghịch với r².'],['Vận tốc thoát khỏi Trái Đất khoảng:',['11,2 km/s','1,1 km/s','112 km/s','0,1 km/s'],0,'Tính từ √(2GM/r).'],['Edmond Halley đã dự đoán điều gì?',['Sao chổi quay lại năm 1758','Sự tồn tại của Hải Vương tinh','Nhật thực năm 2000','Hố đen'],0,'Dự đoán đúng sau khi ông qua đời.'],['Newton công bố định luật hấp dẫn trong sách:',['Principia (1687)','Almagest','Sidereus Nuncius','Astronomia Nova'],0,'Philosophiæ Naturalis Principia Mathematica.']]]);
