function dome(){const g=$('#dm2').getContext('2d'),dv=$('#ld').value,d=dv?new Date(dv):new Date(),jd=d/864e5+2440587.5,lst=((280.46061837+360.98564736629*(jd-2451545)+LOC.lon)%360+360)%360,la=LOC.lat*R_,C=210,Rr=196,sa=SKYR.sun==null?-30:SKYR.sun;
const P=(ra,de)=>{const H=(lst-ra*15)*R_,dd=de*R_,al=Math.asin(Math.sin(la)*Math.sin(dd)+Math.cos(la)*Math.cos(dd)*Math.cos(H));return[al/R_,Math.atan2(Math.sin(H),Math.cos(H)*Math.sin(la)-Math.tan(dd)*Math.cos(la))+Math.PI]},XY=(al,az)=>{const r=(90-al)/90*Rr;return[C-r*Math.sin(az),C-r*Math.cos(az)]};
g.fillStyle='#05070d';g.fillRect(0,0,420,420);g.fillStyle=sa>0?'#5b8fd1':sa>-6?'#2b3a67':sa>-18?'#10183a':'#04060d';g.beginPath();g.arc(C,C,Rr,0,7);g.fill();g.strokeStyle='rgba(255,255,255,.2)';[30,60].forEach(a=>{g.beginPath();g.arc(C,C,(90-a)/90*Rr,0,7);g.stroke()});g.beginPath();g.arc(C,C,Rr,0,7);g.stroke();g.fillStyle='#cfd3dc';g.font='bold 12px sans-serif';g.fillText('B',C-4,C-Rr+14);g.fillText('N',C-4,C+Rr-4);g.fillText('Đ',C-Rr+4,C+4);g.fillText('T',C+Rr-14,C+4);
const yr=(jd-2451545)/365.25,pos=ST.map(s=>{const a=s[1]*15*R_,q=s[2]*R_;return P(s[1]+(3.075+1.336*Math.sin(a)*Math.tan(q))*yr/3600,s[2]+20.04*Math.cos(a)*yr/3600)}),nm=$('#dmn').checked;
if($('#dml').checked){g.strokeStyle='rgba(120,170,255,.55)';CL.forEach(l=>{g.beginPath();let on=0;l.forEach(i=>{const p=pos[i];if(p[0]<0){on=0;return}const q=XY(p[0],p[1]);on?g.lineTo(q[0],q[1]):g.moveTo(q[0],q[1]);on=1});g.stroke()})}
ST.forEach((s,i)=>{const p=pos[i];if(p[0]<0)return;const q=XY(p[0],p[1]);g.fillStyle='#fff';g.beginPath();g.arc(q[0],q[1],Math.max(.9,3.1-.65*s[3]),0,7);g.fill();if(nm&&s[3]<1.2){g.fillStyle='#ffe9b0';g.font='10px sans-serif';g.fillText(s[0],q[0]+5,q[1]-4)}});
$('#dv').textContent='Đang trên trời (cao hơn 15°): '+CN.filter(c=>pos[c[1]][0]>15).map(c=>c[0]).join(', ')+'.';if(nm){g.fillStyle='#9ec1ff';g.font='11px sans-serif';CN.forEach(c=>{const p=pos[c[1]];if(p[0]>0){const q=XY(p[0],p[1]);g.fillText(c[0],q[0]+6,q[1]+14)}})}
const B=[['sun','Mặt Trời','#ffd45c',9],['moon','Mặt Trăng','#eee',7]];PL.forEach((p,i)=>{if(i!=2)B.push([i,p[0],p[3],5])});B.forEach(b=>{const a=SKYR[b[0]],z=SKYA[b[0]];if(a>0){const q=XY(a,z*R_);g.fillStyle=b[2];g.beginPath();g.arc(q[0],q[1],b[3],0,7);g.fill();g.fillStyle='#fff';g.font='11px sans-serif';g.fillText(b[1],q[0]+b[3]+3,q[1]+3)}})}
$('#dml').onchange=$('#dmn').onchange=dome;
