function seas(){const g=$('#sc2').getContext('2d'),d=+$('#sdr').value,cx=210,cy=100,rx=150,ry=45,b=Math.PI+2*Math.PI*(d-172)/365.25,x=cx+rx*Math.cos(b),y=cy-ry*Math.sin(b),lr=LOC.lat*R_,dec=k=>-23.44*Math.cos(2*Math.PI*(k+10)/365.25),hr=k=>Math.acos(Math.max(-1,Math.min(1,-Math.tan(lr)*Math.tan(dec(k)*R_))))/R_*2/15,de=dec(d),H=hr(d),t=23.44*R_;
g.fillStyle='#05070d';g.fillRect(0,0,420,300);g.strokeStyle='rgba(255,255,255,.25)';g.lineWidth=1;g.beginPath();g.ellipse(cx,cy,rx,ry,0,0,7);g.stroke();g.fillStyle='#ffc04d';g.beginPath();g.arc(cx,cy,16,0,7);g.fill();
g.fillStyle='#2a63b5';g.beginPath();g.arc(x,y,12,0,7);g.fill();const an=Math.atan2(cy-y,cx-x);g.fillStyle='#4f9de0';g.beginPath();g.arc(x,y,12,an-Math.PI/2,an+Math.PI/2);g.fill();g.strokeStyle='#8cf';g.lineWidth=2;g.beginPath();g.moveTo(x+Math.sin(t)*24,y-Math.cos(t)*24);g.lineTo(x-Math.sin(t)*24,y+Math.cos(t)*24);g.stroke();
let mn=99,mxh=0;for(let k=1;k<=365;k+=7){const h=hr(k);mn=Math.min(mn,h);mxh=Math.max(mxh,h)}g.strokeStyle='#f0b429';g.lineWidth=1.5;g.beginPath();for(let k=1;k<=365;k+=3){const px=20+k/365*380,py=285-(hr(k)-mn)/(mxh-mn+.01)*70;k==1?g.moveTo(px,py):g.lineTo(px,py)}g.stroke();const mx2=20+d/365*380,my2=285-(H-mn)/(mxh-mn+.01)*70;g.fillStyle='#fff';g.beginPath();g.arc(mx2,my2,4,0,7);g.fill();g.font='11px sans-serif';g.fillText('Độ dài ngày tại '+LOC.name+': '+mn.toFixed(1)+' đến '+mxh.toFixed(1)+' giờ',20,205);
const ds=new Date(2026,0,d).toLocaleDateString('vi-VN',{day:'numeric',month:'long'}),se=d>=80&&d<172?'xuân':d>=172&&d<266?'hè':d>=266&&d<355?'thu':'đông';$('#sdv').textContent=ds;
$('#sti').innerHTML=`${ds}: mùa ${se} ở Bắc bán cầu. Xích vĩ Mặt Trời ${de.toFixed(1)}°. Tại ${LOC.name}: ngày dài ${H.toFixed(1)} giờ, Mặt Trời giữa trưa cao ${(90-Math.abs(LOC.lat-de)).toFixed(0)}°. Mùa do trục nghiêng 23,4° gây ra, không phải do khoảng cách tới Mặt Trời (Trái Đất gần Mặt Trời nhất vào đầu tháng 1).`}
