const OB=[['Mặt Trăng','Dọc đường phân chia sáng tối thấy hố rõ nhất; từ 50 mm.'],['Mộc tinh và 4 vệ tinh Galileo','Dải mây mờ và 4 chấm sáng thẳng hàng; từ 60 mm, 50×.'],['Sao Thổ và vành đai','Vành đai thấy từ 50×; khe Cassini cần 100 mm trở lên.'],['Kim tinh có pha','Pha lưỡi liềm hoặc bán nguyệt như Mặt Trăng; từ 60 mm.'],['Mizar và Alcor (Đại Hùng)','Cặp sao đôi tách được bằng mắt thường; kính cho thấy thêm Mizar B.'],['Albireo (Thiên Nga)','Sao đôi màu cam và xanh, đẹp nhất ở khoảng 50×.'],['Quần sao Thất Nữ (M45)','Chùm sao xanh sáng ở Kim Ngưu; dùng ống nhòm hoặc 30×.'],['Tinh vân Orion (M42)','Đám sáng xanh lục ở kiếm Orion, từ 70 mm; mùa đông.'],['Thiên hà Andromeda (M31)','Vệt mờ hình bầu dục, cần trời tối; mùa thu.'],['Hỏa tinh khi xung đối','Đĩa nhỏ màu cam, cần từ 100 mm và vài trăm lần.']];
let od={};try{od=JSON.parse(localStorage.getItem('obs')||'{}')}catch(e){}
function obsr(){const n=Object.keys(od).length;$('#obs').innerHTML=`<h2>Thử thách quan sát (${n}/${OB.length})</h2><p class='s'>Đánh dấu khi bạn đã nhìn thấy. Xem bảng Thiên thể trên trời ở trên để biết thứ gì đang lên.</p>`+OB.map((o,i)=>`<label class='ck'><input type='checkbox' data-ob='${i}' ${od[i]?'checked':''}><span><b>${o[0]}</b>: ${o[1]}</span></label>`).join('')}
document.addEventListener('change',e=>{const i=e.target.dataset&&e.target.dataset.ob;if(i===undefined)return;e.target.checked?od[i]=1:delete od[i];try{localStorage.setItem('obs',JSON.stringify(od))}catch(x){}obsr()});
LS.push(['Ánh sáng và quang phổ',3,'Năm 1814, Joseph Fraunhofer cho ánh sáng Mặt Trời đi qua lăng kính và thấy hàng trăm vạch đen mảnh. Năm 1868, một vạch vàng lạ trong quang phổ Mặt Trời dẫn tới nguyên tố mới, được đặt tên helium theo thần Mặt Trời Helios; mãi đến năm 1895 người ta mới tìm thấy helium trên Trái Đất.',['Ánh sáng là sóng điện từ: từ sóng vô tuyến, hồng ngoại, ánh sáng nhìn thấy (khoảng 400–700 nm), tử ngoại tới tia X và tia gamma.','Quang phổ liên tục đến từ vật rắn nóng; vạch phát xạ từ khí nóng loãng; vạch hấp thụ khi ánh sáng đi qua khí lạnh. Mỗi nguyên tố có bộ vạch riêng như dấu vân tay.','Định luật Wien: λmax = 2.898.000 nm·K ÷ T; sao càng nóng càng xanh, càng lạnh càng đỏ.','Hiệu ứng Doppler: vật lùi xa làm vạch dịch về phía đỏ, lại gần thì dịch về phía xanh; từ đó đo được vận tốc.'],[[['T','Nhiệt độ bề mặt T (K)',5772]],v=>`Bước sóng phát mạnh nhất ≈ ${(2.898e6/v.T).toFixed(0)} nm.`],[['Vạch hấp thụ xuất hiện khi:',['Ánh sáng đi qua khí lạnh','Vật rắn nóng phát sáng','Khí nóng loãng phát sáng','Ánh sáng đi trong chân không'],0,'Khí lạnh hấp thụ đúng các bước sóng đặc trưng.'],['Sao nào nóng nhất?',['Sao xanh','Sao vàng','Sao đỏ','Sao cam'],0,'Càng nóng càng xanh.'],['Nguyên tố nào được tìm thấy trên Mặt Trời trước khi tìm thấy trên Trái Đất?',['Helium','Oxy','Sắt','Vàng'],0,'Phát hiện qua quang phổ năm 1868.'],['Vạch quang phổ dịch về phía đỏ cho biết nguồn:',['Đang lùi xa','Đang lại gần','Đứng yên','Đang nguội đi'],0,'Hiệu ứng Doppler.'],['Mặt Trời (5.772 K) phát mạnh nhất ở bước sóng khoảng:',['500 nm','50 nm','5.000 nm','50.000 nm'],0,'2.898.000 ÷ 5.772 ≈ 502 nm.']]],['Mặt Trời của chúng ta',2,'Năm 1611, Galileo và Christoph Scheiner độc lập thấy vết đen trên Mặt Trời. Năm 1843, Heinrich Schwabe sau 17 năm đếm vết đen nhận ra chu kỳ khoảng 11 năm. Ngày 1 tháng 9 năm 1859, Richard Carrington thấy một chớp sáng lớn trên vết đen; chưa đầy một ngày sau (khoảng 17,5 giờ), cơn bão từ mạnh nhất từng ghi nhận làm cực quang lan tới vùng nhiệt đới và làm hỏng điện báo.',['Mặt Trời chứa 99,86% khối lượng Hệ Mặt Trời; lõi khoảng 15 triệu K tổng hợp hydro thành helium; bề mặt khoảng 5.772 K.','Vết đen là vùng lạnh hơn (khoảng 3.500–4.500 K) do từ trường mạnh; số vết đen đạt cực đại mỗi khoảng 11 năm.','Gió Mặt Trời và các vụ phun trào hạt tới Trái Đất gây cực quang và có thể làm hỏng vệ tinh.','Mặt Trời biến khoảng 4 triệu tấn khối lượng mỗi giây thành năng lượng theo E = mc².','AN TOÀN: chỉ quan sát qua màng lọc Mặt Trời chuẩn gắn phía trước ống kính; kính râm thường và phim ảnh cũ không an toàn.'],[[['m','Khối lượng chuyển hóa mỗi giây (kg)',4e9]],v=>`Công suất ≈ ${(v.m*9e16).toExponential(2)} W (E = mc²).`],[['Vết đen Mặt Trời tối vì:',['Lạnh hơn vùng xung quanh','Không có ánh sáng','Là lỗ thủng','Là bóng hành tinh'],0,'Từ trường mạnh làm chúng lạnh hơn.'],['Chu kỳ vết đen khoảng:',['11 năm','1 năm','100 năm','1 tháng'],0,'Schwabe phát hiện năm 1843.'],['Năng lượng Mặt Trời đến từ:',['Tổng hợp hạt nhân hydro','Đốt cháy than','Phân rã uranium','Ma sát'],0,'Hydro thành helium ở lõi.'],['Cách quan sát Mặt Trời an toàn là:',['Màng lọc Mặt Trời gắn phía trước ống kính','Kính râm đeo sau thị kính','Nhìn nhanh vài giây','Phim chụp ảnh cũ'],0,'Phải chặn ánh sáng trước khi vào kính.'],['Chớp sáng năm 1859 gắn với tên:',['Carrington','Galileo','Herschel','Halley'],0,'Sự kiện Carrington.']]],['Vòng đời sao và hố đen',3,'Năm 1967, nghiên cứu sinh Jocelyn Bell phát hiện nguồn sóng vô tuyến nhấp nháy đều như đồng hồ: đó là pulsar, sao neutron quay nhanh. Năm 1930, Chandrasekhar tính ra rằng sao lùn trắng nặng quá khoảng 1,4 lần Mặt Trời sẽ sụp đổ. Năm 2019, Kính Chân trời Sự kiện chụp bóng của hố đen ở tâm thiên hà M87, ảnh đầu tiên của loại thiên thể này.',['Sao hình thành từ tinh vân; phần lớn đời sống ở dãy chính, đốt hydro thành helium.','Sao giống Mặt Trời thành khổng lồ đỏ rồi lùn trắng; sao nặng hơn nổ siêu tân tinh để lại sao neutron hoặc hố đen.','Sao neutron nặng cỡ 1,4 Mặt Trời nhưng bán kính chỉ khoảng 10–12 km.','Bán kính Schwarzschild r = 2GM/c² ≈ 2,95 km cho mỗi khối lượng Mặt Trời: ranh giới mà ánh sáng cũng không thoát ra được.','Siêu tân tinh 1572 (Tycho) và 1604 (Kepler) là hai lần cuối thấy trong Ngân Hà bằng mắt thường.'],[[['M','Khối lượng hố đen (lần Mặt Trời)',10]],v=>`Bán kính Schwarzschild ≈ ${(2.953*v.M).toFixed(1)} km.`],[['Mặt Trời sẽ kết thúc đời mình thành:',['Sao lùn trắng','Hố đen','Sao neutron','Siêu tân tinh'],0,'Không đủ nặng để nổ hay thành hố đen.'],['Pulsar là:',['Sao neutron quay nhanh','Hành tinh','Sao chổi','Tinh vân'],0,'Phát xung đều đặn khi quay.'],['Hố đen nặng 10 lần Mặt Trời có bán kính Schwarzschild khoảng:',['30 km','3 km','300 km','3.000 km'],0,'2,95 km × 10.'],['Giới hạn Chandrasekhar khoảng:',['1,4 khối lượng Mặt Trời','14 khối lượng Mặt Trời','0,14 khối lượng Mặt Trời','100 khối lượng Mặt Trời'],0,'Vượt giới hạn, sao lùn trắng sụp đổ.'],['Ai phát hiện pulsar đầu tiên năm 1967?',['Jocelyn Bell','Edwin Hubble','Henrietta Leavitt','Carl Sagan'],0,'Cùng giáo sư hướng dẫn Antony Hewish.']]],['Thiên hà và vũ trụ',3,'Năm 1920, Harlow Shapley và Heber Curtis tranh luận xem các tinh vân xoắn ốc nằm trong hay ngoài Ngân Hà. Năm 1924 Hubble đo khoảng cách Andromeda và phân xử: đó là một thiên hà khác. Năm 1965, Penzias và Wilson tình cờ bắt được tiếng nhiễu 2,7 K từ mọi hướng, ánh sáng còn lại của Vũ trụ sơ khai.',['Ngân Hà là thiên hà xoắn ốc có thanh, rộng khoảng 100.000 năm ánh sáng, chứa hàng trăm tỉ sao; Mặt Trời nằm ở rìa một nhánh xoắn.','Ba loại chính: xoắn ốc, elip, bất định; Ngân Hà và Andromeda thuộc Nhóm Địa phương và sẽ va chạm sau vài tỉ năm.','Định luật Hubble: v = H₀·d, với H₀ khoảng 70 km/s/Mpc; thiên hà càng xa càng lùi nhanh.','Vũ trụ khoảng 13,8 tỉ năm tuổi theo mô hình Big Bang; bức xạ nền vũ trụ 2,7 K là một bằng chứng.','Vật chất thông thường chỉ khoảng 5% tổng năng lượng Vũ trụ; phần còn lại là vật chất tối và năng lượng tối.'],[[['d','Khoảng cách (Mpc)',100],['H','H₀ (km/s/Mpc)',70]],v=>`Vận tốc lùi xa ≈ ${(v.H*v.d).toFixed(0)} km/s, bằng ${(v.H*v.d/299792*100).toFixed(2)}% tốc độ ánh sáng.`],[['Hubble năm 1924 chứng minh điều gì?',['Andromeda là thiên hà khác','Trái Đất phẳng','Mặt Trời là trung tâm','Có hố đen'],0,'Ông đo được khoảng cách tới Andromeda.'],['Theo định luật Hubble, thiên hà xa hơn thì:',['Lùi ra xa nhanh hơn','Lùi chậm hơn','Cùng tốc độ','Đứng yên'],0,'v tỉ lệ thuận với d.'],['Bức xạ nền vũ trụ có nhiệt độ khoảng:',['2,7 K','270 K','27.000 K','0 K'],0,'Phát hiện năm 1965.'],['Tuổi Vũ trụ khoảng:',['13,8 tỉ năm','138 triệu năm','1,38 nghìn tỉ năm','4,5 tỉ năm'],0,'Theo mô hình Big Bang.'],['Ngân Hà thuộc loại thiên hà:',['Xoắn ốc có thanh','Elip','Bất định','Thấu kính'],0,'Có thanh ở giữa.']]],['Quan sát thực hành từ Hà Nội',1,'Từ 1758 đến 1781, Charles Messier săn sao chổi và liên tục gặp những vệt mờ không di chuyển làm hỏng cuộc săn; ông bèn lập danh sách để tránh nhầm lẫn. Danh sách Messier (ông công bố 103 vật thể; người đời sau bổ sung thành 110) ngày nay là bài tập nhập môn của mọi người quan sát nghiệp dư.',['Thích nghi bóng tối cần 20–30 phút; dùng đèn đỏ mờ để không mất.','Ô nhiễm ánh sáng làm mờ sao: ở thành phố bạn thấy sao tới cấp 3–4, nơi tối tới cấp 6.','Ở Hà Nội, trời thường trong nhất vào mùa thu và đầu đông (khoảng tháng 10 đến tháng 12); cuối đông và xuân hay mưa phùn, nồm ẩm; mùa hè nhiều mây giông.','Mặt Trăng và hành tinh quan sát tốt ngay trong thành phố; tinh vân, thiên hà mờ cần chỗ tối.','Ghi nhật ký (ngày giờ, kính, thị kính, seeing, hình vẽ) giúp bạn tiến bộ; dùng mục Thử thách quan sát.'],[[['D','Khẩu độ (mm)',150],['L','Số cấp sao mất do ánh sáng thành phố',2]],v=>`Sao mờ nhất thấy được ≈ cấp ${(2.7+5*Math.log10(v.D)-v.L).toFixed(1)}.`],[['Thích nghi bóng tối cần khoảng:',['20–30 phút','1 giây','5 giờ','1 ngày'],0,'Mắt cần thời gian để nhạy hơn.'],['Loại đèn nên dùng khi quan sát:',['Đèn đỏ mờ','Đèn pin trắng sáng','Đèn LED xanh','Đèn flash'],0,'Ánh sáng đỏ ít làm mất thích nghi.'],['Mục tiêu nào quan sát tốt ngay trong thành phố?',['Mặt Trăng và hành tinh','Thiên hà mờ','Tinh vân mờ','Sao chổi mờ'],0,'Vì chúng rất sáng.'],['Danh sách Messier lập ra để:',['Tránh nhầm vệt mờ với sao chổi','Đặt tên hành tinh','Tính lịch','Đo khoảng cách'],0,'Messier săn sao chổi.'],['Ô nhiễm ánh sáng làm:',['Giảm số sao mờ thấy được','Tăng số sao thấy được','Không ảnh hưởng','Làm sao sáng hơn'],0,'Nền trời sáng che sao mờ.']]]);
let cd={},ci=0,QP=[];try{cd=JSON.parse(localStorage.getItem('cur')||'{}')}catch(e){}
function cur(){const n=LS.length,dn=Object.keys(cd).length,L=LS[ci],LV=['','Nhập môn','Hệ Mặt Trời','Quang học và Vũ trụ'];
QP=L[5].map(q=>{const a=q[1].map((_,j)=>j);for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a});
$('#cur').innerHTML=`<div class="sum"><h2>Chương trình học: ${n} bài, 3 cấp</h2><span class="s">Hoàn thành ${dn}/${n} bài · đạt khi đúng từ 3/5 câu</span></div><div class="bar" style="margin-top:8px"><i style="width:${dn/n*100}%"></i></div>
<div class="les"><nav class="lnav" aria-label="Danh sách bài">${[1,2,3].map(k=>{const a=LS.map((l,i)=>[l,i]).filter(x=>x[0][1]==k),d2=a.filter(x=>cd[x[1]]).length;return `<h3>Cấp ${k} · ${LV[k]} · ${d2}/${a.length}${d2==a.length?' · ★ huy hiệu':''}</h3>`+a.map(([l,i])=>`<button data-ci="${i}" class="${i==ci?'on':''} ${cd[i]?'dn':''}"><span>${cd[i]?'✓':i+1}</span>${l[0]}</button>`).join('')}).join('')}</nav>
<div class="lbody"><h3>Bài ${ci+1} · Cấp ${L[1]} · ${LV[L[1]]}</h3><h2 style="font-size:1.45rem">${L[0]}</h2><p class="story">${L[2]}</p><h3>Ý chính</h3><ul>${L[3].map(x=>`<li>${x}</li>`).join('')}</ul><div id="tl"></div><h3>Câu hỏi đánh giá</h3>${L[5].map((q,k)=>`<div class="q"><p><b>${k+1}. ${q[0]}</b></p>${QP[k].map(j=>`<label class="ck"><input type="radio" name="q${k}" value="${j}"><span>${q[1][j]}</span></label>`).join('')}<div id="ex${k}" class="s"></div></div>`).join('')}<p class="row"><button class="b" data-qg="1">Nộp bài</button><button class="b gh" data-ci="${ci}">Làm lại, xáo đáp án</button><span id="qr"></span></p></div></div>`;tool()}

function tool(){const T=LS[ci][4],el=$('#tl');if(!T){el.innerHTML='';return}if(T=='moon'){el.innerHTML="<button class='b' data-mo='1'>Mở mô phỏng pha Mặt Trăng</button>";return}el.innerHTML=`<div class='q'><b>Thực hành tính toán</b>`+T[0].map(f=>`<label>${f[1]}</label><input type='number' step='any' data-tf='${f[0]}' value='${f[2]}'>`).join('')+`<p id='to' style='font-weight:600;color:var(--hi)'></p></div>`;tc()}
function tc(){const T=LS[ci][4];if(!T||T=='moon')return;const v={};document.querySelectorAll('[data-tf]').forEach(i=>v[i.dataset.tf]=+i.value);$('#to').textContent=T[1](v)}
function qg(){const L=LS[ci];let s=0;L[5].forEach((q,k)=>{const r=document.querySelector('input[name=q'+k+']:checked'),ok=r&&+r.value==q[2];if(ok)s++;$('#ex'+k).innerHTML=`<span class='${ok?'okk':'w'}'>${ok?'Đúng.':'Chưa đúng.'}</span> ${q[3]}`});$('#qr').textContent='Điểm: '+s+'/'+L[5].length+(s>=3?' — Hoàn thành bài!':' — Hãy đọc lại và thử lại.');if(s>=3){cd[ci]=1;try{localStorage.setItem('cur',JSON.stringify(cd))}catch(e){}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ci],[data-qg],[data-mo]');if(!b)return;if(b.dataset.ci!==undefined){ci=+b.dataset.ci;cur();if(innerWidth<760)$('.lbody').scrollIntoView({block:'start'})}else if(b.dataset.qg!==undefined)qg();else show('solar')});
document.addEventListener('input',e=>{if(e.target.dataset&&e.target.dataset.tf)tc()});
const R_=Math.PI/180,LOC={lat:21.03,lon:105.85,name:'Hà Nội'},SKYR={},SKYA={};let live=1,cutOn=0;
const EL=[[.38709927,.00000037,.20563593,.00001906,7.00497902,-.00594749,252.2503235,149472.67411175,77.45779628,.16047689,48.33076593,-.12534081],[.72333566,.0000039,.00677672,-.00004107,3.39467605,-.0007889,181.9790995,58517.81538729,131.60246718,.00268329,76.67984255,-.27769418],[1.00000261,.00000562,.01671123,-.00004392,-.00001531,-.01294668,100.46457166,35999.37244981,102.93768193,.32327364,0,0],[1.52371034,.00001847,.0933941,.00007882,1.84969142,-.00813131,-4.55343205,19140.30268499,-23.94362959,.44441088,49.55953891,-.29257343],[5.202887,-.00011607,.04838624,-.00013253,1.30439695,-.00183714,34.39644051,3034.74612775,14.72847983,.21252668,100.47390909,.20469106],[9.53667594,-.0012506,.05386179,-.00050991,2.48599187,.00193609,49.95424423,1222.49362201,92.59887831,-.41897216,113.66242448,-.28867794],[19.18916464,-.00196176,.04725744,-.00004397,.77263783,-.00242939,313.23810451,428.48202785,170.9542763,.40805281,74.01692503,.04240589],[30.06992276,.00026291,.00859048,.00005105,1.77004347,.00035372,-55.12002969,218.45945325,44.96476227,-.32241464,131.78422574,-.00508664]];
