function hel(i,T){const q=EL[i],a=q[0]+q[1]*T,e=q[2]+q[3]*T,I=(q[4]+q[5]*T)*R_,w=q[8]+q[9]*T,Od=q[10]+q[11]*T,M=(((q[6]+q[7]*T-w)%360)+360)%360*R_;let E=M;for(let k=0;k<12;k++)E=M+e*Math.sin(E);const xp=a*(Math.cos(E)-e),yp=a*Math.sqrt(1-e*e)*Math.sin(E),o=(w-Od)*R_,O=Od*R_,co=Math.cos(o),so=Math.sin(o),cO=Math.cos(O),sO=Math.sin(O),cI=Math.cos(I),sI=Math.sin(I);return[(co*cO-so*sO*cI)*xp+(-so*cO-co*sO*cI)*yp,(co*sO+so*cO*cI)*xp+(-so*sO+co*cO*cI)*yp,so*sI*xp+co*sI*yp]}
const LP=[['Hà Nội',21.03,105.85],['Hải Phòng',20.86,106.68],['Sa Pa (trời tối)',22.34,103.84],['Mộc Châu (trời tối)',20.85,104.63],['Huế',16.46,107.59],['Đà Nẵng',16.05,108.2],['Nha Trang',12.24,109.19],['Đà Lạt',11.94,108.44],['TP. Hồ Chí Minh',10.82,106.63],['Cần Thơ',10.03,105.78],['Tùy chọn',0,0]];
$('#lp').innerHTML=LP.map((p,i)=>`<option value='${i}'>${p[0]}</option>`).join('');
const setL=(la,lo,n)=>{LOC.lat=la;LOC.lon=lo;LOC.name=n;$('#la').value=la;$('#lo').value=lo;sky();sim()};
$('#lp').onchange=e=>{const p=LP[e.target.value];if(p[0]!='Tùy chọn')setL(p[1],p[2],p[0])};
$('#la').onchange=$('#lo').onchange=()=>{LOC.lat=+$('#la').value;LOC.lon=+$('#lo').value;LOC.name='vị trí của bạn';$('#lp').value=LP.length-1;sky();sim()};
