function e2q(v){const[x,y,z]=v;return[x,y*Math.cos(EPS)-z*Math.sin(EPS),y*Math.sin(EPS)+z*Math.cos(EPS)]}
function radec(v){const q=e2q(v);return[Math.atan2(q[1],q[0]),Math.atan2(q[2],Math.hypot(q[0],q[1]))]}
