const MSH=[['Quadrantids (Mục Phu)',1,3,110,'sau nửa đêm, hướng Đông Bắc'],['Lyrids (Thiên Cầm)',4,22,18,'sau nửa đêm, hướng Đông Bắc'],['Eta Aquariids (Bảo Bình)',5,6,50,'rạng sáng, hướng Đông'],['Delta Aquariids (Bảo Bình)',7,30,25,'sau nửa đêm, hướng Nam'],['Perseids (Anh Tiên)',8,12,100,'sau nửa đêm, hướng Đông Bắc'],['Draconids (Thiên Long)',10,8,10,'đầu tối, hướng Bắc'],['Orionids (Lạp Hộ)',10,21,20,'sau nửa đêm, hướng Đông'],['Leonids (Sư Tử)',11,17,15,'rạng sáng, hướng Đông'],['Geminids (Song Tử)',12,14,150,'gần như cả đêm, đẹp nhất sau 22 giờ'],['Ursids (Tiểu Hùng)',12,22,10,'rạng sáng, hướng Bắc']];
