const EVK={thuc:'Nhật/nguyệt thực',xung:'Xung đối',gian:'Kim/Thủy tinh',gan:'Hành tinh gặp nhau',sao:'Mưa sao băng'};let EVS=null,evOn=new Set(Object.keys(EVK));
