R.push(['Vật tư','Sơn đen mờ, giấy nhung đen, keo PVA, keo epoxy, silicone trung tính',1,SRC.paint,null],['In 3D',t=='new'?'Giá gương phụ, nắp Cheshire, kệ thị kính, adapter điện thoại':'Kệ thị kính, nắp ống, adapter điện thoại',1,SRC.p3d,pr('In 3D')]);
