async function saveFile(name,data,msg){const m=$(msg);try{const dl=window.claude&&await window.claude.use('downloads');if(dl){await dl.save({filename:name,data});m.textContent='Đã lưu '+name+'.';return}}catch(e){if(e&&e.code=='declined'){m.textContent='Bạn đã hủy lưu tệp.';return}}
try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'text/plain'}));a.download=name;document.body.appendChild(a);a.click();a.remove();m.textContent='Đã tải '+name+'.'}catch(e){m.textContent='Trình duyệt này không cho tải tệp; hãy dùng nút Chép.'}}
async function copyText(t,msg){try{await navigator.clipboard.writeText(t);$(msg).textContent='Đã chép vào bộ nhớ tạm.'}catch(e){const ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');$(msg).textContent='Đã chép vào bộ nhớ tạm.'}catch(x){$(msg).textContent='Không chép được; hãy bôi đen bảng để chép.'}ta.remove()}}

