let SL=[{t:'ref',D:102,fr:9,m:'eq',e:[1,2],x:['red','sun'],ex:1},{t:'new',D:150,fr:8,m:'dob',e:[1,2],x:['red','sun'],ex:1},{t:'sct',D:203,fr:10,m:'goa',e:[1,2],x:['red','sun','dew'],ex:1}];
try{const v=JSON.parse(localStorage.getItem('slots')||'null');if(Array.isArray(v)&&v.length==3)SL=v}catch(e){}
function cmpMetrics(c){return withCfg({t:c.t,D:c.D,fr:c.fr,m:c.m,e:c.e,x:c.x},()=>{const D=S.D,F=D*S.fr,d=dims(),mx=Math.max(...ops().map(o=>F/o.f*(o.b?2:1)));return{n:T[S.t].n,cfg:D+' mm f/'+S.fr,F,mt:MT.find(m=>m[0]==S.m)[1],lg:Math.round((D/7)**2),lm:(2.7+5*Math.log10(D)-2).toFixed(1),res:(116/D).toFixed(2),mx:Math.round(mx),L:d.L,a:sum(cost(1)),b:sum(cost(0)),h:S.t=='new'?'60–120':S.t=='ref'?'20–40':'15–30',sat:D>=100&&mx>=120?'Thấy rõ vành, khe Cassini khi trời ổn định':D>=70&&mx>=80?'Thấy vành, chưa tách khe Cassini':'Cần thị kính ngắn hơn hoặc Barlow'}})}
function cmpR(){const M=SL.map(cmpMetrics),rows=[['Loại kính','n'],['Khẩu độ, tỷ số f','cfg'],['Tiêu cự (mm)','F'],['Giá đỡ','mt'],['Thu sáng so với mắt','lg','×'],['Sao mờ nhất (thành phố)','lm',' mag'],['Phân giải Dawes','res','″'],['Phóng đại lớn nhất với thị kính đã chọn','mx','×'],['Chiều dài ống (mm)','L'],['Giờ công tự chế','h'],['Sao Thổ','sat']],best=k=>{const v=M.map(m=>m[k]);return k=='a'||k=='b'?v.indexOf(Math.min(...v)):-1};
$('#cmpc').innerHTML=`<div class="sum"><h2>So sánh 3 cấu hình</h2><span class="s">Bấm “Lưu cấu hình hiện tại” để đưa thiết kế đang chọn vào một ô.</span></div><div class="sc"><table class="cmpt"><tr><th></th>${M.map((m,i)=>`<th>${'ABC'[i]}${SL[i].ex?' <span class="tag">ví dụ</span>':''}</th>`).join('')}</tr>${rows.map(r=>`<tr><td>${r[0]}</td>${M.map(m=>`<td>${typeof m[r[1]]=='number'?m[r[1]].toLocaleString('vi-VN'):m[r[1]]}${r[2]||''}</td>`).join('')}</tr>`).join('')}${[['Chi phí tự chế','a'],['Chi phí mua sẵn','b']].map(([l,k])=>`<tr><td><b>${l}</b></td>${M.map((m,i)=>`<td class="${best(k)==i?'okk':''}"><b>${fm(m[k])}</b></td>`).join('')}</tr>`).join('')}<tr><td></td>${SL.map((_,i)=>`<td><div class="row" style="justify-content:flex-end"><button class="b sm" data-sv="${i}">Lưu cấu hình hiện tại</button><button class="b gh sm" data-ld="${i}">Mở để sửa</button></div></td>`).join('')}</tr></table></div><p class="s">Giá tham khảo, cùng hệ số giá ở cột trái. Màu xanh là rẻ nhất trong hàng.</p>`}
document.addEventListener('click',e=>{const s=e.target.closest('[data-sv]'),l=e.target.closest('[data-ld]');if(s){const i=+s.dataset.sv;SL[i]={t:S.t,D:S.D,fr:S.fr,m:S.m,e:[...S.e],x:[...S.x]};try{localStorage.setItem('slots',JSON.stringify(SL))}catch(x){}cmpR()}if(l){const c=SL[+l.dataset.ld];Object.assign(S,{t:c.t,D:c.D,fr:c.fr,m:c.m,e:[...c.e],x:[...c.x]});build();upd();window.scrollTo({top:0,behavior:'smooth'})}});

