const JT=[['moon','Mặt Trăng',0],['jup','Mộc tinh',1],['sat','Thổ tinh',2],['ven','Kim tinh',3],['mars','Hỏa tinh',9],['mer','Thủy tinh'],['sun','Mặt Trời (có màng lọc)'],['ura','Thiên Vương / Hải Vương tinh'],['dbl','Sao đôi'],['cl','Quần tinh'],['neb','Tinh vân'],['gal','Thiên hà'],['com','Sao chổi'],['met','Mưa sao băng'],['oth','Khác']],SEE=['I – hoàn hảo, ảnh đứng yên','II – rung nhẹ, có lúc rất nét','III – trung bình','IV – rung nhiều, ảnh nhòe','V – rất kém'];
let JL=[],JDB=null,JUID=null,jEdit=null,jDel=null;
try{JL=JSON.parse(localStorage.getItem('log')||'[]')}catch(e){JL=[]}
const jSaveLocal=()=>{try{localStorage.setItem('log',JSON.stringify(JL))}catch(e){}};
async function jInit(){try{if(!window.claude)return;const [db,us]=await Promise.all([window.claude.use('db'),window.claude.use('user')]);if(!db||!us)return;const id=await us.id();if(!id)return;JDB=db.collection('data/users/'+id+'/log/entries');JUID=id;let first=1;
const tm=setTimeout(()=>{if(first)$('#jst').textContent='Chưa kết nối được kho lưu trữ; đang lưu trong trình duyệt này.'},10000);
JDB.onSnapshot(s=>{clearTimeout(tm);const rem=s.docs.map(d=>({...d.data(),id:d.id}));if(first){first=0;const miss=JL.filter(e=>!rem.some(r=>r.id==e.id));miss.forEach(e=>JDB.doc(e.id).set(e).catch(()=>{}));JL=rem.concat(miss)}else JL=rem;jSaveLocal();$('#jst').textContent='Đang lưu vào tài khoản Claude của bạn: xem được trên mọi thiết bị khi mở link này. Chỉ bạn đọc được.';jList()},er=>{$('#jst').textContent='Mất kết nối kho lưu trữ; đang lưu trong trình duyệt này.'})}catch(e){}}
function jPut(e){const i=JL.findIndex(x=>x.id==e.id);i>=0?JL[i]=e:JL.push(e);jSaveLocal();if(JDB)JDB.doc(e.id).set(e).catch(()=>{$('#jm').textContent='Chưa lưu được lên tài khoản; mục vẫn được giữ trong trình duyệt.'});jList()}
function jRemove(id){JL=JL.filter(x=>x.id!=id);jSaveLocal();if(JDB)JDB.doc(id).delete().catch(()=>{});jList()}
const pad=d=>new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,16);
function jForm(e){e=e||{};$('#jd').value=e.dt||pad(new Date());$('#jl').value=e.loc||LOC.name;$('#jtg').value=e.tg||'moon';$('#jtx').value=e.tx||'';$('#jsc').value=e.sc||(T[S.t].n+' '+S.D+' mm f/'+S.fr);const op=ops();$('#jep').innerHTML=op.map(o=>{const g=Math.round(S.D*S.fr/o.f*(o.b?2:1)),v=o.n+' ('+g+'×)';return`<option>${v}</option>`}).join('')+'<option>Khác / mắt thường</option>';if(e.ep){if(![...$('#jep').options].some(o=>o.value==e.ep))$('#jep').insertAdjacentHTML('afterbegin',`<option>${e.ep}</option>`);$('#jep').value=e.ep}$('#jse').value=e.se||'2';$('#jtr').value=e.tr||'3';$('#jno').value=e.no||'';skClear();if(e.sk){const im=new Image();im.onload=()=>$('#jsk').getContext('2d').drawImage(im,0,0);im.src=e.sk}jEdit=e.id||null;$('#jsv').textContent=jEdit?'Lưu thay đổi':'Lưu mục nhật ký';$('#jcn').hidden=!jEdit}
let skD=0,skMark=0;function skClear(){const g=$('#jsk').getContext('2d');g.fillStyle='#05070d';g.fillRect(0,0,240,240);g.strokeStyle='#3a4560';g.lineWidth=2;g.beginPath();g.arc(120,120,116,0,7);g.stroke();skMark=0}
function skInit(){const c=$('#jsk'),g=c.getContext('2d'),P=e=>{const r=c.getBoundingClientRect();return[(e.clientX-r.left)*240/r.width,(e.clientY-r.top)*240/r.height]};c.onpointerdown=e=>{skD=1;c.setPointerCapture(e.pointerId);const[x,y]=P(e);g.beginPath();g.moveTo(x,y)};c.onpointermove=e=>{if(!skD)return;const[x,y]=P(e),er=$('#jer').checked;g.strokeStyle=er?'#05070d':'#e9ecf3';g.lineWidth=er?14:2;g.lineCap='round';g.lineTo(x,y);g.stroke();skMark=1};c.onpointerup=c.onpointercancel=()=>skD=0;$('#jskc').onclick=skClear}
function jList(){const q=($('#jq').value||'').toLowerCase(),f=$('#jf').value,L=JL.filter(e=>(!f||e.tg==f)&&(!q||JSON.stringify([e.tx,e.no,e.loc,e.sc]).toLowerCase().includes(q))).sort((a,b)=>b.dt<a.dt?-1:1),nm=k=>(JT.find(t=>t[0]==k)||[0,k])[1],nights=new Set(JL.map(e=>(e.dt||'').slice(0,10))).size,tgs=new Set(JL.map(e=>e.tg)).size;
$('#jsum').innerHTML=`<div><b>${JL.length}</b><small>mục nhật ký</small></div><div><b>${nights}</b><small>đêm quan sát</small></div><div><b>${tgs}</b><small>loại mục tiêu</small></div>`;
$('#jls').innerHTML=L.length?L.map(e=>`<article class="je">${e.sk?`<img src="${e.sk}" alt="Phác họa ${nm(e.tg)}" width="96" height="96">`:'<div class="jph"></div>'}<div style="min-width:0"><div class="row" style="justify-content:space-between"><b>${nm(e.tg)}${e.tx?': '+esc(e.tx):''}</b><span class="s">${new Date(e.dt).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}</span></div><p class="s">${esc(e.loc)} · ${esc(e.sc)} · ${esc(e.ep)} · seeing ${['','I','II','III','IV','V'][e.se]} · độ trong ${e.tr}/5</p>${e.no?`<p style="margin:4px 0">${esc(e.no)}</p>`:''}<div class="row"><button class="b gh sm" data-je="${e.id}">Sửa</button><button class="b gh sm" data-jd="${e.id}">${jDel==e.id?'Bấm lần nữa để xóa':'Xóa'}</button></div></div></article>`).join(''):`<p class="s">${JL.length?'Không có mục nào khớp bộ lọc.':'Chưa có mục nào. Ghi buổi quan sát đầu tiên bằng biểu mẫu bên cạnh: ngày giờ, mục tiêu, kính, thị kính, seeing và vài dòng ghi chú hoặc một hình phác họa.'}</p>`}
const esc=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function jInitUI(){$('#jtg').innerHTML=JT.map(t=>`<option value="${t[0]}">${t[1]}</option>`).join('');$('#jf').innerHTML='<option value="">Tất cả mục tiêu</option>'+JT.map(t=>`<option value="${t[0]}">${t[1]}</option>`).join('');$('#jse').innerHTML=SEE.map((s,i)=>`<option value="${i+1}">${s}</option>`).join('');skInit();jForm();
$('#jfm').onsubmit=ev=>{ev.preventDefault();const e={id:jEdit||'o'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),dt:$('#jd').value||pad(new Date()),loc:$('#jl').value.slice(0,80),tg:$('#jtg').value,tx:$('#jtx').value.slice(0,120),sc:$('#jsc').value.slice(0,120),ep:$('#jep').value,se:+$('#jse').value,tr:+$('#jtr').value,no:$('#jno').value.slice(0,3000)};const old=JL.find(x=>x.id==e.id);e.sk=skMark?$('#jsk').toDataURL('image/png'):(old&&old.sk||'');jPut(e);const ob=(JT.find(t=>t[0]==e.tg)||[])[2];if(ob!=null&&!od[ob]){od[ob]=1;try{localStorage.setItem('obs',JSON.stringify(od))}catch(x){}obsr();$('#jm').textContent='Đã lưu. Đã đánh dấu thử thách “'+OB[ob][0]+'”.'}else $('#jm').textContent=jEdit?'Đã lưu thay đổi.':'Đã lưu mục mới.';jForm()};
$('#jcn').onclick=()=>{jForm();$('#jm').textContent=''};$('#jq').oninput=$('#jf').onchange=jList;
$('#jls').onclick=e=>{const a=e.target.closest('[data-je]'),b=e.target.closest('[data-jd]');if(a){jForm(JL.find(x=>x.id==a.dataset.je));$('#jfm').scrollIntoView({behavior:'smooth'})}if(b){if(jDel==b.dataset.jd){jRemove(jDel);jDel=null}else{jDel=b.dataset.jd;jList()}}};
$('#jxc').onclick=()=>saveFile('nhat-ky-quan-sat.csv','﻿Ngày giờ,Địa điểm,Mục tiêu,Chi tiết,Kính,Thị kính,Seeing,Độ trong,Ghi chú\n'+JL.map(e=>[e.dt,e.loc,(JT.find(t=>t[0]==e.tg)||[0,e.tg])[1],e.tx,e.sc,e.ep,e.se,e.tr,e.no].map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n'),'#jxm');
$('#jxj').onclick=()=>saveFile('nhat-ky-quan-sat.json',JSON.stringify(JL),'#jxm');
$('#jim').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const a=JSON.parse(r.result);if(!Array.isArray(a))throw 0;let n=0;a.forEach(x=>{if(x&&x.id&&x.dt&&x.tg){jPut({id:String(x.id),dt:String(x.dt),loc:String(x.loc||''),tg:String(x.tg),tx:String(x.tx||''),sc:String(x.sc||''),ep:String(x.ep||''),se:+x.se||3,tr:+x.tr||3,no:String(x.no||''),sk:typeof x.sk=='string'&&x.sk.startsWith('data:image/')?x.sk:''});n++}});$('#jxm').textContent='Đã nhập '+n+' mục.'}catch(x){$('#jxm').textContent='Tệp không đúng định dạng nhật ký (.json xuất từ ứng dụng này).'}};r.readAsText(f);e.target.value=''};
jList();jInit()}

